-- Output
LMG2L["TextLabel_5"] = Instance.new("TextLabel", LMG2L["ImageLabel_2"]);
LMG2L["TextLabel_5"]["BorderSizePixel"] = 0;
LMG2L["TextLabel_5"]["TextSize"] = 14;
LMG2L["TextLabel_5"]["TextXAlignment"] = Enum.TextXAlignment.Left;
LMG2L["TextLabel_5"]["BackgroundTransparency"] = 1;
LMG2L["TextLabel_5"]["Size"] = UDim2.new(0, 276, 0, 48);
LMG2L["TextLabel_5"]["Position"] = UDim2.new(0, 34, 0, 335);
LMG2L["TextLabel_5"]["FontFace"] = Font.new([[rbxasset://fonts/families/Inconsolata.json]]);
LMG2L["TextLabel_5"]["Text"] = "[Rc1.exe FE]: Hazır";
LMG2L["TextLabel_5"]["TextColor3"] = Color3.fromRGB(100, 255, 140);
LMG2L["TextLabel_5"]["TextWrapped"] = true;

-- ====================== FONKSİYONLAR ======================

local function UpdateOutput(msg, color)
	LMG2L["TextLabel_5"].Text = "[Rc1.exe FE]: " .. msg
	LMG2L["TextLabel_5"].TextColor3 = color or Color3.fromRGB(100, 255, 140)
	task.delay(4, function()
		LMG2L["TextLabel_5"].Text = "[Rc1.exe FE]: Hazır"
	end)
end

local function OpenDeveloperConsole()
	pcall(function() StarterGui:SetCore("DevConsoleVisible", true) end)
	task.wait(0.2)
	pcall(function()
		local c = game:GetService("CoreGui"):FindFirstChild("DevConsoleMaster")
		if c and c:FindFirstChild("DevConsoleWindow") then c.DevConsoleWindow.Visible = true end
	end)
	UpdateOutput("Developer Console açıldı!", Color3.fromRGB(100, 200, 255))
end

local function FE_Execute(rawCode)
	if rawCode == "" or rawCode:match("^%s*$") then
		UpdateOutput("Script boş!", Color3.fromRGB(255, 80, 80))
		return
	end

	if rawCode:match("^/console%s*$") or rawCode:lower() == "/console" then
		OpenDeveloperConsole()
		return
	end

	UpdateOutput("Çalıştırılıyor...", Color3.fromRGB(255, 200, 80))

	local success, err = pcall(function()
		-- require( ID ).Function() desteği
		if rawCode:match("require%s*%(%s*%d") then
			-- Direkt require çağırma
			loadstring(rawCode)()
			return
		end

		-- Genel FE wrapper
		local feCode = [[
			local code = ]] .. HttpService:JSONEncode(rawCode) .. [[
			pcall(function()
				loadstring(code)()
			end)
		]]
		loadstring(feCode)()
	end)

	if success then
		UpdateOutput("Script çalıştırıldı!", Color3.fromRGB(0, 255, 100))
	else
		UpdateOutput("Hata: " .. tostring(err), Color3.fromRGB(255, 80, 80))
	end
end

-- Butonlar
LMG2L["TextButton2_9"].MouseButton1Click:Connect(function()
	local code = LMG2L["TextBox_f"].Text
	FE_Execute(code)
end)

LMG2L["TextButton_6"].MouseButton1Click:Connect(function()
	LMG2L["TextBox_f"].Text = ""
	UpdateOutput("Input temizlendi.")
end)

LMG2L["TextButton3_d"].MouseButton1Click:Connect(function()
	LMG2L["ScreenGui_1"]:Destroy()
end)

print("Rc1.exe yüklendi!")
